// Export bounded native analysis observations from an owned headless project.
// @category Independent
import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileResults;
import ghidra.program.model.address.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.symbol.*;
import ghidra.program.model.mem.*;
import ghidra.program.model.block.*;
import ghidra.program.model.pcode.*;
import ghidra.program.model.data.*;
import ghidra.program.model.lang.Register;
import ghidra.program.model.scalar.Scalar;
import ghidra.program.database.mem.FileBytes;
import java.util.*;
import java.nio.file.*;
import java.security.MessageDigest;

public class RealExport extends GhidraScript {
  Map<String,Object> map(Object... a){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)m.put(a[i].toString(),a[i+1]);return m;}
  String addr(Address a){return a==null?null:a.getAddressSpace().getName().equals("ram")?"0x"+Long.toUnsignedString(a.getOffset(),16):a.toString();}
  String json(Object v){if(v==null)return "null";if(v instanceof String){String s=(String)v;StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray()){if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof Map){List<String> items=new ArrayList<>();for(Object k:((Map<?,?>)v).keySet())items.add(json(k.toString())+":"+json(((Map<?,?>)v).get(k)));return "{"+String.join(",",items)+"}";}if(v instanceof Iterable){List<String> items=new ArrayList<>();for(Object x:(Iterable<?>)v)items.add(json(x));return "["+String.join(",",items)+"]";}return json(v.toString());}
  String architecture(){String p=currentProgram.getLanguage().getProcessor().toString().toLowerCase(Locale.ROOT);int bits=currentProgram.getLanguage().getDefaultSpace().getSize();return p.equals("x86")?(bits==64?"x86_64":"x86"):p.equals("aarch64")?"arm64":p.equals("arm")?"arm":p;}
  String bytes(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x&255));return s.toString();}
  String fileHash(FileBytes file,boolean modified) throws Exception {MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] chunk=new byte[65536];for(long offset=0;offset<file.getSize();){monitor.checkCancelled();int n=(int)Math.min(chunk.length,file.getSize()-offset);int got=modified?file.getModifiedBytes(offset,chunk,0,n):file.getOriginalBytes(offset,chunk,0,n);if(got!=n)throw new IllegalStateException("Short provider file-byte read");md.update(chunk,0,n);offset+=n;}return bytes(md.digest());}
  Map<String,Object> loadObservations(List<String> limits) throws Exception {
    List<Object> files=new ArrayList<>(),mappings=new ArrayList<>(),entries=new ArrayList<>(),contexts=new ArrayList<>(),captures=new ArrayList<>();List<FileBytes> sourceFiles=currentProgram.getMemory().getAllFileBytes();Map<FileBytes,Integer> fileIndexes=new HashMap<>();long captured=0;
    boolean dos=currentProgram.getLanguageID().toString().contains(":16:");
    for(FileBytes file:sourceFiles){monitor.checkCancelled();if(file.getSize()>64L*1024*1024){limits.add("Provider file-byte hashes omitted above 64 MiB");continue;}fileIndexes.put(file,files.size());files.add(map("name",file.getFilename(),"size",file.getSize(),"original_sha256",fileHash(file,false),"modified_sha256",fileHash(file,true)));}
    for(MemoryBlock block:currentProgram.getMemory().getBlocks())for(MemoryBlockSourceInfo source:block.getSourceInfos()){
      monitor.checkCancelled();FileBytes file=source.getFileBytes().orElse(null);long relative=source.getFileBytesOffset();Long offset=file!=null&&relative>=0?file.getFileOffset()+relative:null;String sha=null,hexBytes=null;
      if(dos&&block.isInitialized()&&source.getLength()<=2L*1024*1024-captured){byte[] memory=new byte[(int)source.getLength()];int got=currentProgram.getMemory().getBytes(source.getMinAddress(),memory);if(got!=memory.length)throw new IllegalStateException("Short provider memory read");sha=bytes(MessageDigest.getInstance("SHA-256").digest(memory));hexBytes=bytes(memory);captured+=memory.length;}
      else if(dos&&block.isInitialized())limits.add("DOS loaded-byte capture limited to 2 MiB");
      mappings.add(map("block",block.getName(),"start",addr(source.getMinAddress()),"end",addr(source.getMaxAddress().add(1)),"address_space",source.getMinAddress().getAddressSpace().getName(),"initialized",block.isInitialized(),"loaded",block.isLoaded(),"overlay",block.isOverlay(),"length",source.getLength(),"source_file_index",file==null?null:fileIndexes.get(file),"file_offset",offset,"sha256",sha));
      if(hexBytes!=null)captures.add(map("start",addr(source.getMinAddress()),"bytes_hex",hexBytes));
    }
    AddressIterator it=currentProgram.getSymbolTable().getExternalEntryPointIterator();while(it.hasNext()&&entries.size()<10000){Address a=it.next();entries.add(addr(a));List<Object> registers=new ArrayList<>();if(dos)for(String name:new String[]{"CS","IP","SS","SP","DS","ES"}){Register r=currentProgram.getRegister(name);java.math.BigInteger value=r==null?null:currentProgram.getProgramContext().getValue(r,a,false);registers.add(map("name",name,"value_hex",value==null?null:"0x"+value.toString(16)));}contexts.add(map("address",addr(a),"registers",registers));}
    return map("executable_format",currentProgram.getExecutableFormat(),"language_id",currentProgram.getLanguageID().toString(),"compiler_spec_id",currentProgram.getCompilerSpec().getCompilerSpecID().toString(),"image_base",addr(currentProgram.getImageBase()),"default_address_space",currentProgram.getAddressFactory().getDefaultAddressSpace().getName(),"source_files",files,"mappings",mappings,"relocations",new ArrayList<>(),"entry_points",entries,"entry_context",contexts,"loaded_bytes",captures);
  }
  Object nullableSize(int size){return size<0?null:size;}
  List<Object> operandComponents(Instruction instruction,int index){
    List<Object> result=new ArrayList<>();Object[] values=instruction.getOpObjects(index);if(values==null)return result;
    for(Object value:values){if(value instanceof Register){Register r=(Register)value;result.add(map("kind","register","text",r.getName(),"value",r.getName(),"bit_width",r.getBitLength()));}
      else if(value instanceof Scalar){Scalar s=(Scalar)value;result.add(map("kind","immediate","text",s.toString(),"value",s.getBigInteger().toString(),"bit_width",s.bitLength()));}
      else if(value instanceof Address){Address a=(Address)value;result.add(map("kind","address","text",a.toString(),"value",addr(a),"bit_width",a.getAddressSpace().getSize()));}
      else result.add(map("kind","unknown","text",String.valueOf(value),"value",null,"bit_width",null));}
    return result;
  }
  Map<String,Object> apiValue(Integer ordinal,String name,DataType type,VariableStorage storage,String role){return map("ordinal",ordinal,"name",name,"data_type",type.getName(),"size_bytes",nullableSize(type.getLength()),"storage",storage==null?null:storage.toString(),"confidence","medium","evidence",List.of(map("kind","decompiler-type","source","ghidra-high-function-prototype","detail","Type and storage recovered by the configured decompiler")),"decompiler_artifacts",List.of("recovered-signature","register-or-stack-storage"),"role",role);}
  List<Object> jumpTables(HighFunction high){List<Object> result=new ArrayList<>();JumpTable[] tables=high.getJumpTables();if(tables==null)return result;for(JumpTable table:tables){List<Object> sources=new ArrayList<>(),mappings=new ArrayList<>();List<Object> evidence=List.of(map("kind","jump-table","source","ghidra-high-function-jump-table","detail","Jump-table record recovered by the configured decompiler"));JumpTable.LoadTable[] loads=table.getLoadTables();if(loads!=null)for(JumpTable.LoadTable load:loads)sources.add(map("address",addr(load.getAddress()),"provenance","ghidra-decompiler-load-table","entry_size_bytes",load.getSize()>0?load.getSize():null,"entry_count",load.getNum(),"confidence","medium","evidence",evidence));Address[] cases=table.getCases();Integer[] labels=table.getLabelValues();if(cases!=null)for(int i=0;i<cases.length;i++)mappings.add(map("case_value",labels!=null&&i<labels.length?labels[i]:null,"target_address",addr(cases[i]),"confidence","medium","evidence",evidence));result.add(map("dispatch_address",addr(table.getSwitchAddress()),"data_sources",sources,"mappings",mappings,"default_targets",new ArrayList<>(),"limitations",List.of("Default targets and architecture-specific table encodings are not separately established")));}return result;}
  Map<String,Object> api(Function f,HighFunction high){
    if(high==null)return map("available",false,"reason","Decompiler returned no high-function prototype","residual_unknowns",List.of("Calling convention and parameter storage unavailable"));
    FunctionPrototype proto=high.getFunctionPrototype();List<Object> parameters=new ArrayList<>();for(int i=0;i<proto.getNumParams();i++){HighSymbol p=proto.getParam(i);if(p!=null)parameters.add(apiValue(i,p.getName(),p.getDataType(),p.getStorage(),"parameter"));}
    return map("available",true,"provenance","ghidra-high-function-prototype","signature_source",f.getSignatureSource().toString(),"calling_convention",proto.getModelName()==null?"unknown":proto.getModelName(),"return_type",apiValue(null,null,proto.getReturnType(),proto.getReturnStorage(),"return"),"parameters",parameters,"jump_tables",jumpTables(high),"pseudocode",map("classification","decompiler-generated-non-source","compilable",false),"decompiler_artifacts",List.of("recovered-signature","register-and-stack-variables","compiler-generated-control-flow","pseudocode"),"limitations",List.of("Recovered ABI facts are provider analysis, not original source declarations"));
  }
  Map<String,Object> varnode(Varnode v){return v==null?null:map("kind",v.isConstant()?"constant":v.isRegister()?"register":v.isUnique()?"unique":v.isAddress()?"address":"other","size_bytes",v.getSize(),"location",v.isConstant()?null:addr(v.getAddress()),"constant_hex",v.isConstant()?Long.toUnsignedString(v.getOffset(),16):null);}
  Map<String,Object> valueFlow(HighFunction high,Function f)throws Exception {
    if(high==null)return map("available",false,"reason","Decompiler returned no high p-code graph","limitations",List.of("No SSA edges are guessed from disassembly"));
    List<PcodeOpAST> ops=new ArrayList<>();Iterator<PcodeOpAST> iter=high.getPcodeOps();while(iter.hasNext()&&ops.size()<20000){monitor.checkCancelled();ops.add(iter.next());}boolean truncated=iter.hasNext();Map<PcodeOp,String> ids=new IdentityHashMap<>();for(int i=0;i<ops.size();i++)ids.put(ops.get(i),addr(f.getEntryPoint())+":pcode:"+i);
    List<Object> operations=new ArrayList<>(),edges=new ArrayList<>(),effects=new ArrayList<>(),params=new ArrayList<>(),uses=new ArrayList<>();int omittedInputs=0,omittedEdges=0;
    FunctionPrototype proto=high.getFunctionPrototype();for(int i=0;i<proto.getNumParams();i++){HighSymbol p=proto.getParam(i);if(p!=null)params.add(map("ordinal",i,"name",p.getName()==null?"parameter_"+i:p.getName(),"data_type",p.getDataType().getName()));}
    for(int i=0;i<ops.size();i++){monitor.checkCancelled();PcodeOpAST op=ops.get(i);String id=ids.get(op);List<Object> inputs=new ArrayList<>();for(int j=0;j<op.getNumInputs();j++){Varnode v=op.getInput(j);inputs.add(varnode(v));PcodeOp def=v.getDef();if(def!=null){if(ids.containsKey(def))edges.add(map("definition",ids.get(def),"use",id,"input_index",j));else omittedEdges++;}HighVariable variable=v.getHigh();if(variable instanceof HighParam)uses.add(map("ordinal",((HighParam)variable).getSlot(),"use",id,"input_index",j));}
      operations.add(map("id",id,"address",addr(op.getSeqnum().getTarget()),"sequence",i,"opcode",op.getMnemonic(),"is_dead",op.isDead(),"block_membership",op.getParent()==null?"detached":"member","inputs",inputs,"output",varnode(op.getOutput())));
      int code=op.getOpcode();String effect=code==PcodeOp.LOAD?"memory_read":code==PcodeOp.STORE?"memory_write":code==PcodeOp.CBRANCH?"conditional_branch":code==PcodeOp.BRANCHIND?"indirect_branch":code==PcodeOp.CALL?"direct_call":code==PcodeOp.CALLIND?"indirect_call":null;if(effect!=null)effects.add(map("operation",id,"kind",effect,"operand_input",code==PcodeOp.LOAD||code==PcodeOp.STORE?1:0,"value_input",code==PcodeOp.STORE?Integer.valueOf(2):code==PcodeOp.CBRANCH?Integer.valueOf(1):null));
    }
    return map("available",true,"provenance","ghidra-high-pcode","operations",operations,"def_use",edges,"effects",effects,"parameters",params,"parameter_uses",uses,"truncated",truncated,"omitted_operations_lower_bound",truncated?1:0,"known_omitted_inputs",omittedInputs,"known_omitted_edges",omittedEdges,"limitations",List.of("Def-use is intra-function SSA; runtime values and alias-sensitive interprocedural effects remain unknown"));
  }
  Map<String,Object> dataType(DataType dt){List<Object> fields=new ArrayList<>(),members=new ArrayList<>();String kind=dt instanceof Structure?"struct":dt instanceof Union?"union":dt instanceof ghidra.program.model.data.Enum?"enum":dt instanceof Pointer?"pointer":dt instanceof Array?"array":dt instanceof TypeDef?"typedef":"scalar";DataType ref=dt instanceof Pointer?((Pointer)dt).getDataType():dt instanceof Array?((Array)dt).getDataType():dt instanceof TypeDef?((TypeDef)dt).getBaseDataType():null;
    if(dt instanceof Composite)for(DataTypeComponent component:((Composite)dt).getComponents()){DataType type=component.getDataType();BitFieldDataType bit=type instanceof BitFieldDataType?(BitFieldDataType)type:null;fields.add(map("ordinal",component.getOrdinal(),"name",component.getFieldName(),"offset_bytes",component.getOffset(),"size_bytes",nullableSize(component.getLength()),"type_id",type.getPathName(),"bit_size",bit==null?null:bit.getBitSize(),"bit_offset",bit==null?null:bit.getBitOffset(),"status","observed","flexible_tail","unknown"));}
    if(dt instanceof ghidra.program.model.data.Enum){ghidra.program.model.data.Enum e=(ghidra.program.model.data.Enum)dt;for(String name:e.getNames())members.add(map("name",name,"value",Long.toString(e.getValue(name))));}
    return map("status","available","reason",null,"id",dt.getPathName(),"name",dt.getName(),"kind",kind,"source","analysis-database","source_archive",dt.getSourceArchive()==null?null:dt.getSourceArchive().getName(),"address",null,"size_bytes",nullableSize(dt.getLength()),"alignment_bytes",nullableSize(dt.getAlignment()),"packing_enabled",dt instanceof Composite?((Composite)dt).isPackingEnabled():null,"referenced_type",ref==null?null:ref.getPathName(),"array_count",dt instanceof Array?((Array)dt).getNumElements():null,"array_stride_bytes",dt instanceof Array?((Array)dt).getElementLength():null,"fields",fields,"members",members,"total_fields",fields.size(),"truncated",false,"limitations",List.of("Layout is observed in the analysis database; it may include recovered or imported types"));
  }
  public void run() throws Exception {
    String[] args=getScriptArgs();if(args.length<1||args.length>2)throw new IllegalArgumentException("Expected owned output path and optional owned source path");
    String sourceSha=null;if(args.length==2){Path source=Path.of(args[1]).toAbsolutePath().normalize(),destination=Path.of(args[0]).toAbsolutePath().normalize();if(!source.getParent().toRealPath().equals(destination.getParent().toRealPath())||!Files.isRegularFile(source,LinkOption.NOFOLLOW_LINKS))throw new IllegalArgumentException("Source identity must refer to the explicit regular owned input beside the output");sourceSha=bytes(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(source)));}
    List<Object> funcs=new ArrayList<>(),insts=new ArrayList<>(),refs=new ArrayList<>(),syms=new ArrayList<>(),segs=new ArrayList<>(),strings=new ArrayList<>(),types=new ArrayList<>(),definedTypes=new ArrayList<>();List<String> limits=new ArrayList<>();
    for(MemoryBlock b:currentProgram.getMemory().getBlocks()){monitor.checkCancelled();segs.add(map("name",b.getName(),"start",addr(b.getStart()),"end",addr(b.getEnd().add(1)),"read",b.isRead(),"write",b.isWrite(),"execute",b.isExecute(),"initialized",b.isInitialized(),"overlay",b.isOverlay(),"address_space",b.getStart().getAddressSpace().getName()));}
    SymbolIterator si=currentProgram.getSymbolTable().getAllSymbols(true);while(si.hasNext()&&syms.size()<200000){monitor.checkCancelled();Symbol s=si.next();syms.add(map("address",addr(s.getAddress()),"name",s.getName(),"source",s.getSource().toString(),"external",s.isExternal(),"type",s.getSymbolType().toString()));}if(si.hasNext())limits.add("Symbol inventory limited to 200000 records");
    DecompInterface decompiler=new DecompInterface();decompiler.toggleJumpLoads(true);decompiler.openProgram(currentProgram);BasicBlockModel blocks=new BasicBlockModel(currentProgram);
    try{FunctionIterator fi=currentProgram.getFunctionManager().getFunctions(true);while(fi.hasNext()&&funcs.size()<10000){monitor.checkCancelled();Function f=fi.next();List<Object> ranges=new ArrayList<>(),basic=new ArrayList<>(),locals=new ArrayList<>();AddressRangeIterator ri=f.getBody().getAddressRanges();while(ri.hasNext()){AddressRange r=ri.next();ranges.add(map("start",addr(r.getMinAddress()),"end",addr(r.getMaxAddress().add(1))));}
      CodeBlockIterator bi=blocks.getCodeBlocksContaining(f.getBody(),monitor);while(bi.hasNext()){CodeBlock block=bi.next();List<String> successors=new ArrayList<>();CodeBlockReferenceIterator dests=block.getDestinations(monitor);while(dests.hasNext())successors.add(addr(dests.next().getDestinationAddress()));basic.add(map("start",addr(block.getMinAddress()),"end",addr(block.getMaxAddress().add(1)),"successors",successors));}
      for(Variable v:f.getLocalVariables())locals.add(map("description",v.toString(),"provenance","ghidra-local-variable","name",v.getName(),"stack_displacement",v.isStackVariable()?Integer.toString(v.getStackOffset()):null));
      DecompileResults dr=decompiler.decompileFunction(f,30,monitor);String pseudo=dr.decompileCompleted()&&dr.getDecompiledFunction()!=null?dr.getDecompiledFunction().getC():null;
      HighFunction high=dr.getHighFunction();funcs.add(map("address",addr(f.getEntryPoint()),"name",f.getName(),"external",f.isExternal(),"thunk",f.isThunk(),"thunk_target",f.isThunk()&&f.getThunkedFunction(true)!=null?addr(f.getThunkedFunction(true).getEntryPoint()):null,"ranges",ranges,"total_bytes",f.getBody().getNumAddresses(),"signature",f.getSignature().toString(),"locals",locals,"basic_blocks",basic,"pseudocode",pseudo,"native_api",api(f,high),"native_value_flow",valueFlow(high,f),"decompiler_error",pseudo==null?dr.getErrorMessage():null));
    }if(fi.hasNext())limits.add("Function inventory limited to 10000 records");}finally{decompiler.dispose();}
    InstructionIterator ii=currentProgram.getListing().getInstructions(true);while(ii.hasNext()&&insts.size()<1000000){monitor.checkCancelled();Instruction i=ii.next();FlowType flow=i.getFlowType();List<Object> operands=new ArrayList<>();for(int j=0;j<i.getNumOperands();j++)operands.add(map("index",j,"raw",i.getDefaultOperandRepresentation(j),"provider_type",i.getOperandType(j),"components",operandComponents(i,j),"memory_addressing","unavailable"));List<String> destinations=new ArrayList<>();for(Address a:i.getFlows())destinations.add(addr(a));Function f=currentProgram.getFunctionManager().getFunctionContaining(i.getAddress());insts.add(map("address",addr(i.getAddress()),"procedure",f==null?null:addr(f.getEntryPoint()),"bytes",bytes(i.getBytes()),"length",i.getLength(),"mnemonic",i.getMnemonicString(),"text",i.toString(),"operands",operands,"flow",map("kind",flow.isCall()?"call":flow.isJump()?"jump":flow.isTerminal()?"terminal":"fallthrough","conditional",flow.isConditional(),"computed",flow.isComputed(),"direct_destinations",destinations)));
      for(Reference ref:i.getReferencesFrom()){RefType rt=ref.getReferenceType();refs.add(map("source",addr(ref.getFromAddress()),"target",addr(ref.getToAddress()),"type",rt.toString(),"call",rt.isCall(),"jump",rt.isJump(),"data",rt.isData(),"read",rt.isRead(),"write",rt.isWrite(),"flow",rt.isFlow(),"indirect",rt.isIndirect(),"computed",rt instanceof FlowType?((FlowType)rt).isComputed():false,"conditional",rt instanceof FlowType?((FlowType)rt).isConditional():false,"terminal",rt instanceof FlowType?((FlowType)rt).isTerminal():false,"primary",ref.isPrimary(),"operand_index",ref.getOperandIndex(),"external",ref.isExternalReference()));if(refs.size()>=1000000){limits.add("Reference inventory limited to 1000000 records");break;}}
    }if(ii.hasNext())limits.add("Instruction inventory limited to 1000000 records");
    DataIterator di=currentProgram.getListing().getDefinedData(true);int dataRecords=0;while(di.hasNext()&&dataRecords++<100000){monitor.checkCancelled();Data d=di.next();definedTypes.add(map("address",addr(d.getAddress()),"type_id",d.getDataType().getPathName()));if(d.hasStringValue())strings.add(map("address",addr(d.getAddress()),"value",d.getValue().toString(),"length",d.getLength(),"encoding","provider-string"));}if(di.hasNext())limits.add("Defined data inventory limited to 100000 records");
    Iterator<DataType> ti=currentProgram.getDataTypeManager().getAllDataTypes();while(ti.hasNext()&&types.size()<20000){monitor.checkCancelled();types.add(dataType(ti.next()));}if(ti.hasNext())limits.add("Data type inventory limited to 20000 records");
    Map<String,Object> out=map("protocol","real-native-model-v1","provider","ghidra","architecture",architecture(),"language_id",currentProgram.getLanguageID().toString(),"compiler_spec_id",currentProgram.getCompilerSpec().getCompilerSpecID().toString(),"image_base",addr(currentProgram.getImageBase()),"format",currentProgram.getExecutableFormat(),"source_sha256",sourceSha,"functions",funcs,"instructions",insts,"symbols",syms,"references",refs,"segments",segs,"strings",strings,"types",types,"defined_types",definedTypes,"limitations",limits);
    out.put("load_observations",loadObservations(limits));
    Files.writeString(Path.of(args[0]),json(out),StandardOpenOption.CREATE_NEW);
  }
}
